import pandas as pd

def main():
    try:
        # Load data from CSV
        data = pd.read_csv('data.csv')

        # Ensure data is properly formatted
        if not set(data['species'].unique()).issubset({'kelp', 'urchin'}):
            raise ValueError("Invalid species in data")

        # Pivot data to compare kelp and urchin counts directly
        pivoted_data = data.pivot(index='site_id', columns='species', values='count')

        # Compare urchin and kelp counts
        urchin_greater_than_kelp = (pivoted_data['urchin'] > pivoted_data['kelp'])

        # Count the number of sites where urchin count is greater than kelp count
        count = urchin_greater_than_kelp.sum()

        print(count)

    except FileNotFoundError:
        print("The file 'data.csv' was not found.")
    except pd.errors.EmptyDataError:
        print("The file 'data.csv' is empty.")
    except pd.errors.ParserError:
        print("Error parsing 'data.csv'. Please check the file format.")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

