import pandas as pd

def main():
    try:
        # Load the CSV file
        df = pd.read_csv('data.csv')

        # Ensure 'temperature' column exists and is numeric
        if 'temperature' not in df.columns:
            raise ValueError("The 'temperature' column does not exist in the CSV file.")
        df['temperature'] = pd.to_numeric(df['temperature'], errors='coerce')

        # Group rows by whether 'temperature' is above or below 20
        df['temperature_group'] = pd.cut(df['temperature'], 
                                        bins=[df['temperature'].min(), 20, df['temperature'].max()], 
                                        labels=['Below 20', 'Above 20'], 
                                        include_lowest=True)

        # Print the count of rows in each group
        print(df['temperature_group'].value_counts())

    except FileNotFoundError:
        print("The file 'data.csv' was not found.")
    except pd.errors.EmptyDataError:
        print("The file 'data.csv' is empty.")
    except pd.errors.ParserError:
        print("Error parsing the file 'data.csv'.")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

